class Solution { fun isOneEditDistance(s0: String, t0: String): Boolean { var s = s0; var t = t0; if (kotlin.math.abs(s.length - t.length) > 1 || s == t) return false; if (s.length > t.length) { val temp = s; s = t; t = temp }; var i = 0; while (i < s.length && s[i] == t[i]) i++; return if (s.length == t.length) s.substring(i + 1) == t.substring(i + 1) else s.substring(i) == t.substring(i + 1) } }